# ---- layout.py ----
DEFAULTS = dict(
    col_gap=60,       # horizontal gap between columns (beyond node width)
    row_gap=60,       # vertical gap between rows (beyond node height)
    dock_gap=20,      # vertical gap between a host and its docked nodes
    band_gap=100,     # gap between the main graph and the disconnected band
    group_gap=100,    # horizontal gap between group blocks
    group_pad=30,     # padding of group boxes (left/right/bottom)
    group_title=60,   # extra padding at the top of group boxes (title bar)
    sweeps=4,         # barycenter sweeps
)


def _opts(kw):
    o = dict(DEFAULTS)
    for k, v in kw.items():
        if k not in o:
            raise TypeError("unknown layout option %r" % k)
        o[k] = v
    return o


# ---------------------------------------------------------------- graph utils

def _acyclic(ids, edges):
    """Drop self loops, duplicates and DFS back edges (feedback). Deterministic."""
    idset = set(ids)
    out = {i: [] for i in ids}
    seen = set()
    for a, b in edges:
        if a == b or a not in idset or b not in idset or (a, b) in seen:
            continue
        seen.add((a, b))
        out[a].append(b)
    state = {}
    kept = []
    for root in ids:
        if root in state:
            continue
        stack = [(root, iter(out[root]))]
        state[root] = 1
        while stack:
            n, it = stack[-1]
            adv = False
            for m in it:
                s = state.get(m, 0)
                if s == 1:
                    continue          # back edge: feedback, ignored for layout
                kept.append((n, m))
                if s == 0:
                    state[m] = 1
                    stack.append((m, iter(out[m])))
                    adv = True
                    break
            if not adv:
                state[n] = 2
                stack.pop()
    return kept


def _longest_path(ids, edges):
    """ids: ordered list. Returns ({id: layer}, kept_edges)."""
    kept = _acyclic(ids, edges)
    preds = {i: [] for i in ids}
    succs = {i: [] for i in ids}
    indeg = {i: 0 for i in ids}
    for a, b in kept:
        preds[b].append(a)
        succs[a].append(b)
        indeg[b] += 1
    layer = {i: 0 for i in ids}
    queue = [i for i in ids if indeg[i] == 0]
    while queue:
        n = queue.pop(0)
        for m in succs[n]:
            layer[m] = max(layer[m], layer[n] + 1)
            indeg[m] -= 1
            if indeg[m] == 0:
                queue.append(m)
    return layer, kept


# ---------------------------------------------------------------- blocks

class _Block(object):
    """A host node plus the nodes docked under it, treated as one rectangle."""

    def __init__(self, host, members, dock_gap):
        self.id = host["id"]
        self.kind = host.get("kind")
        self.members = [host] + members
        self.offsets = {}     # member id -> (dx, dy) from block top-left, y down
        y = 0
        w = 0
        for i, m in enumerate(self.members):
            if i:
                y += dock_gap
            self.offsets[m["id"]] = (0, y)
            y += m["h"]
            w = max(w, m["w"])
        self.w = w
        self.h = y
        self.ox = host.get("x", 0)
        self.oy = host.get("y", 0) + host["h"]    # original top-left (y up)
        self.x = 0
        self.y = 0   # top-left of block after layout, y up


def _make_blocks(nodes, dock_gap):
    byid = {}
    for n in nodes:
        if n["id"] in byid:
            raise ValueError("duplicate node id %r" % (n["id"],))
        byid[n["id"]] = n

    def root(n):
        seen = set()
        while n.get("docked_to") in byid and n["id"] not in seen:
            seen.add(n["id"])
            n = byid[n["docked_to"]]
        return n

    kids = {}
    for n in nodes:
        r = root(n)
        if r is not n:
            kids.setdefault(r["id"], []).append(n)
    blocks = []
    owner = {}
    for n in nodes:
        if root(n) is n:
            ms = sorted(kids.get(n["id"], []), key=lambda m: (-m.get("y", 0), str(m["id"])))
            b = _Block(n, ms, dock_gap)
            blocks.append(b)
            for m in b.members:
                owner[m["id"]] = b.id
    return blocks, owner


def _reading_key(b):
    return (-b.oy, b.ox, str(b.id))


# ---------------------------------------------------------------- one scope

def _layout_scope(blocks, edges, o):
    """Lay out blocks (with block-level edges). Positions are relative: the
    layout's top-left is (0, 0) and y decreases downward. Sets b.x / b.y.
    Returns (width, height)."""
    blocks = sorted(blocks, key=_reading_key)
    ids = [b.id for b in blocks]
    byid = {b.id: b for b in blocks}
    linked = set()
    for a, b in edges:
        if a != b and a in byid and b in byid:
            linked.add(a)
            linked.add(b)
    main = [b for b in blocks if b.id in linked]
    rest = [b for b in blocks if b.id not in linked]

    width = 0
    height = 0
    if main:
        mids = [b.id for b in main]
        layer, kept = _longest_path(mids, edges)
        ncols = max(layer.values()) + 1
        for b in main:
            if b.kind == "out":
                layer[b.id] = ncols - 1
            elif b.kind == "in":
                layer[b.id] = 0
        cols = [[] for _ in range(ncols)]
        for b in main:
            cols[layer[b.id]].append(b)
        # edges between kept layer-ordered nodes (forced in/out never reverses an edge
        # in a sane network; reversed ones are simply drawn backwards)
        nbr = {i: [] for i in mids}
        for a, b in kept:
            nbr[a].append(b)
            nbr[b].append(a)

        def stack(col):
            ys = {}
            cur = 0
            for b in col:
                ys[b.id] = cur
                cur += b.h + o["row_gap"]
            return ys, max(cur - o["row_gap"], 0)

        pos = {}   # id -> center y (down positive)
        for col in cols:
            ys, _ = stack(col)
            for b in col:
                pos[b.id] = ys[b.id] + b.h / 2.0

        def sweep(order):
            for ci in order:
                col = cols[ci]
                keyed = []
                for k, b in enumerate(col):
                    ns = [n for n in nbr[b.id] if layer[n] != ci]
                    if ns:
                        bc = sum(pos[n] for n in ns) / float(len(ns))
                    else:
                        bc = pos[b.id]
                    keyed.append((bc, k, b))
                keyed.sort(key=lambda t: (t[0], t[1]))
                col[:] = [t[2] for t in keyed]
                ys, _ = stack(col)
                for b in col:
                    pos[b.id] = ys[b.id] + b.h / 2.0

        fwd = list(range(ncols))
        for _ in range(o["sweeps"]):
            sweep(fwd)
            sweep(fwd[::-1])

        colw = [max(b.w for b in c) if c else 0 for c in cols]
        heights = [stack(c)[1] for c in cols]
        height = max(heights)
        x = 0
        for ci, col in enumerate(cols):
            ys, h = stack(col)
            top = (height - h) / 2.0
            for b in col:
                b.x = x
                b.y = -(top + ys[b.id])
            x += colw[ci] + o["col_gap"]
        width = x - o["col_gap"]

    if rest:
        def rk(b):
            r = 0 if b.kind == "in" else (2 if b.kind == "out" else 1)
            return (r,) + _reading_key(b)
        rest.sort(key=rk)
        target = max(width, 1200 if not main else 0, max(b.w for b in rest))
        top = -(height + (o["band_gap"] if main else 0))
        cx = 0
        rowh = 0
        cy = top
        maxw = 0
        for b in rest:
            if cx > 0 and cx + b.w > target:
                cy -= rowh + o["row_gap"]
                cx = 0
                rowh = 0
            b.x = cx
            b.y = cy
            cx += b.w + o["col_gap"]
            maxw = max(maxw, cx - o["col_gap"])
            rowh = max(rowh, b.h)
        width = max(width, maxw)
        height = -(cy - rowh)
    return width, height


# ---------------------------------------------------------------- public

def layout(nodes, edges, return_groups=False, **kw):
    """Compute new positions.

    Returns {id: (x, y)}; with return_groups=True returns (positions, boxes)
    where boxes = {group: (x, y, w, h)} (bottom-left origin, includes padding and
    title bar) so a caller can resize Annotate COMPs.
    """
    o = _opts(kw)
    nodes = list(nodes)
    if not nodes:
        return ({}, {}) if return_groups else {}
    blocks, owner = _make_blocks(nodes, o["dock_gap"])
    bedges = []
    for a, b in edges:
        if a in owner and b in owner and owner[a] != owner[b]:
            bedges.append((owner[a], owner[b]))
    byid = {b.id: b for b in blocks}
    gof = {}
    for b in blocks:
        gof[b.id] = b.members[0].get("group")

    gnames = []
    for b in blocks:
        g = gof[b.id]
        if g not in gnames:
            gnames.append(g)
    # one scope per group (None = ungrouped)
    ext = {}
    for g in gnames:
        bs = [b for b in blocks if gof[b.id] == g]
        be = [e for e in bedges if gof[e[0]] == g and gof[e[1]] == g]
        w, h = _layout_scope(bs, be, o)
        ext[g] = (w, h, bs)

    anchor_x = min(n.get("x", 0) for n in nodes)
    anchor_y = max(n.get("y", 0) + n["h"] for n in nodes)
    boxes = {}
    if len(gnames) == 1 and gnames[0] is None:
        pass
    else:
        # order scopes left -> right by group-level data flow, then original x
        order = [g for g in gnames]
        order.sort(key=lambda g: (min(b.ox for b in ext[g][2]), str(g)))
        gedges = []
        for a, b in bedges:
            if gof[a] != gof[b]:
                gedges.append((gof[a], gof[b]))
        glayer, _ = _longest_path(order, gedges)
        order.sort(key=lambda g: (glayer[g], min(b.ox for b in ext[g][2]), str(g)))
        pad, title = o["group_pad"], o["group_title"]
        cx = 0
        for g in order:
            w, h, bs = ext[g]
            if g is None:
                for b in bs:
                    b.x += cx
                cx += w + o["group_gap"]
            else:
                for b in bs:
                    b.x += cx + pad
                    b.y -= title
                bw, bh = w + 2 * pad, h + pad + title
                boxes[g] = [cx, -bh, bw, bh]
                cx += bw + o["group_gap"]
    pos = {}
    for b in blocks:
        for m in b.members:
            dx, dy = b.offsets[m["id"]]
            pos[m["id"]] = (b.x + dx + anchor_x,
                            b.y - dy - m["h"] + anchor_y)
    out_boxes = {}
    for g, (x, y, w, h) in boxes.items():
        out_boxes[g] = (x + anchor_x, y + anchor_y, w, h)
    return (pos, out_boxes) if return_groups else pos


# ---- overlap.py ----
def _block_owner(nodes):
    byid = {n["id"]: n for n in nodes}
    owner = {}
    for n in nodes:
        cur, seen = n, set()
        while cur.get("docked_to") in byid and cur["id"] not in seen:
            seen.add(cur["id"])
            cur = byid[cur["docked_to"]]
        owner[n["id"]] = cur["id"]
    return owner


def find_overlaps(nodes, margin=10):
    """Pairs (id_a, id_b) of nodes whose rectangles, with `margin` of clearance
    required between them, intersect.  Nodes in the same host+docked block are
    never reported against each other, but docked children are checked against
    every other block."""
    owner = _block_owner(nodes)
    h = margin / 2.0
    items = sorted(
        ((n["x"] - h, n["x"] + n["w"] + h, n["y"] - h, n["y"] + n["h"] + h, n["id"])
        for n in nodes), key=lambda t: (t[0], str(t[4])))
    out = []
    for i, a in enumerate(items):
        for b in items[i + 1:]:
            if b[0] >= a[1]:
                break
            if b[2] < a[3] and a[2] < b[3] and owner[a[4]] != owner[b[4]]:
                out.append((a[4], b[4]))
    return out


def outside_groups(nodes, boxes):
    """Ids of nodes whose group box (x, y, w, h) does not fully contain them."""
    bad = []
    for n in nodes:
        g = n.get("group")
        if g is None or g not in boxes:
            continue
        x, y, w, h = boxes[g]
        if n["x"] < x or n["y"] < y or n["x"] + n["w"] > x + w or n["y"] + n["h"] > y + h:
            bad.append(n["id"])
    return bad


# ---- td_adapter.py ----
def _is_annotate(o):
    return getattr(o, "type", None) == "annotate"


def _has_external_tox(o):
    try:
        p = o.par.externaltox
    except Exception:
        return False
    try:
        return bool(str(p.eval()).strip())
    except Exception:
        return False


SKIP_TAG = "no_arrange"


def _skipped(c):
    """COMPs tagged 'no_arrange' are left alone (and not recursed into), e.g. deliberately messy demo networks."""
    return SKIP_TAG in (getattr(c, "tags", None) or ())


def _child_comps(comp):
    """Child COMPs we recurse into (not Annotates, not externaltox-owned, not tagged no_arrange)."""
    out = []
    for c in comp.children:
        if getattr(c, "isCOMP", False) and not _is_annotate(c) and not _has_external_tox(c) and not _skipped(c):
            out.append(c)
    return out


def _edges(ops, paths):
    edges = []
    seen = set()

    def add(a, b):
        if a != b and a in paths and b in paths and (a, b) not in seen:
            seen.add((a, b))
            edges.append((a, b))

    for o in ops:
        for attr, forward in (("inputConnectors", False), ("outputConnectors", True),
                              ("inputCOMPConnectors", False), ("outputCOMPConnectors", True)):
            try:
                conns = getattr(o, attr, None) or []
                for c in conns:
                    for other in c.connections:
                        oo = other.owner
                        if forward:
                            add(o.path, oo.path)
                        else:
                            add(oo.path, o.path)
            except Exception:
                continue
    return edges


def _gather(comp, annotate_groups):
    kids = list(comp.children)
    annotates = [c for c in kids if _is_annotate(c)]
    ops = [c for c in kids if not _is_annotate(c)]
    paths = set(o.path for o in ops)
    group_of = {}
    if annotate_groups and annotates:
        # smallest enclosing annotate wins (innermost)
        for a in sorted(annotates, key=lambda a: (a.nodeWidth * a.nodeHeight, a.name)):
            try:
                enclosed = list(a.enclosedOPs)
            except Exception:
                enclosed = []
            for e in enclosed:
                if e.path in paths and e.path not in group_of:
                    group_of[e.path] = a.path
    nodes = []
    for o in ops:
        dock = None
        try:
            d = o.dock
            if d is not None and d.path in paths:
                dock = d.path
        except Exception:
            pass
        nodes.append(dict(id=o.path, w=o.nodeWidth, h=o.nodeHeight, x=o.nodeX, y=o.nodeY,
                          docked_to=dock, group=group_of.get(o.path),
                          kind=o.type if o.type in ("in", "out") else None))
    return nodes, _edges(ops, paths), annotates


def _organize_one(comp, annotate_groups):
    nodes, edges, annotates = _gather(comp, annotate_groups)
    before = len(find_overlaps(nodes))
    pos, boxes = layout(nodes, edges, return_groups=True)
    by_path = dict((c.path, c) for c in comp.children)
    ordered = sorted(nodes, key=lambda n: n["docked_to"] is not None)
    for n in ordered:
        o = by_path[n["id"]]
        x, y = pos[n["id"]]
        o.nodeX = int(round(x))
        o.nodeY = int(round(y))
    for a in annotates:
        b = boxes.get(a.path)
        if b is None:
            continue
        a.nodeX = int(round(b[0]))
        a.nodeY = int(round(b[1]))
        a.nodeWidth = int(round(b[2]))
        a.nodeHeight = int(round(b[3]))
    new_nodes = []
    for n in nodes:
        m = dict(n)
        m["x"], m["y"] = int(round(pos[n["id"]][0])), int(round(pos[n["id"]][1]))
        new_nodes.append(m)
    after = len(find_overlaps(new_nodes))
    return dict(nodes=len(nodes), edges=len(edges), groups=len(boxes),
                overlaps_before=before, overlaps_after=after)


def organize(comp, recursive=True, annotate_groups=True):
    """Lay out comp's children (and child COMPs when recursive)."""
    if isinstance(comp, str):
        comp = op(comp)  # noqa: F821
    stats = {}
    todo = [comp]
    while todo:
        c = todo.pop(0)
        stats[c.path] = _organize_one(c, annotate_groups)
        if recursive:
            todo.extend(_child_comps(c))
    return stats


def _check_one(comp):
    nodes, _, _ = _gather(comp, False)
    return [dict(comp=comp.path, a=a, b=b, kind="overlap")
            for a, b in find_overlaps(nodes)]


def check(comp, recursive=True):
    """Return a list of overlap problems ({comp, a, b, kind}) in the tree."""
    if isinstance(comp, str):
        comp = op(comp)  # noqa: F821
    problems = []
    todo = [comp]
    while todo:
        c = todo.pop(0)
        problems.extend(_check_one(c))
        if recursive:
            todo.extend(_child_comps(c))
    return problems


